#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_timeline_document_candidate.h"
int main(){try{SessionTimelineDocumentCandidate doc(loadGraph("work/roundtrip-11.dmx"));auto id=hierarchyRefs(doc.graph(),doc.graph().elements[2470],"timeFrame",1)[0];AnimationTimeFrame before(doc.graph(),doc.graph().elements[id]);auto count=doc.frameCount();auto start=before.start+166;doc.trimClipStart(2470,start);AnimationTimeFrame after(doc.graph(),doc.graph().elements[id]);if(after.start!=start||after.duration!=before.duration-166||after.offset!=before.offset+166||!doc.dirty()||doc.frameCount()!=count)throw std::runtime_error("trim fields");for(int32_t delta:{0,1,167,1000})if(before.childTime(start+delta,false)!=after.childTime(start+delta,false))throw std::runtime_error("trim changed media time");if(doc.undo()!=3||doc.dirty())throw std::runtime_error("grouped undo");AnimationTimeFrame restored(doc.graph(),doc.graph().elements[id]);if(restored.start!=before.start||restored.duration!=before.duration||restored.offset!=before.offset)throw std::runtime_error("undo fields");if(doc.redo()!=3||!doc.dirty())throw std::runtime_error("grouped redo");bool rejected=false;try{doc.trimClipStart(2470,after.start+after.duration);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("invalid trim accepted");auto path="work/trimmed-session-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64())+".dmx";doc.saveAs(path.c_str());auto g=loadGraph(path.c_str());AnimationTimeFrame saved(g,g.elements[id]);if(saved.start!=after.start||saved.offset!=after.offset||doc.dirty())throw std::runtime_error("trim save reload");std::cout<<"timeline trim passed fields=3 media_time_preserved grouped_undo_redo invalid_end_rejected save_reload output="<<path<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
